#!/bin/bash
# Generated by Copilot
# Build script for SunRiseSet program using g++
# Usage: ./build_sunriseset.sh

set -e

# Source directory
SRCDIR="$(cd "$(dirname "$0")" && pwd)"

# Output executable name
OUTPUT="SunRiseSet"

# Compiler settings
CXX="${CXX:-g++}"
CXXFLAGS="-std=c++17 -O2 -Wall -Wextra"

# Define macros to exclude some heavy optional modules for faster compilation
# Also define UNREFERENCED_PARAMETER for non-Windows builds (it's a Windows-only macro)
DEFINES="-DAAPLUS_NO_VSOP87 -DAAPLUS_NO_VSOP2013 -DAAPLUS_NO_ELP2000"

# List of required source files (minimal set needed for sun rise/set calculation)
SOURCES=(
    "SunRiseSet.cpp"
    "AA+.cpp"
    "stdafx.cpp"
    "AADate.cpp"
    "AADynamicalTime.cpp"
    "AARiseTransitSet.cpp"
    "AARiseTransitSet2.cpp"
    "AACoordinateTransformation.cpp"
    "AASidereal.cpp"
    "AANutation.cpp"
    "AAEarth.cpp"
    "AASun.cpp"
    "AAMoon.cpp"
    "AAMercury.cpp"
    "AAVenus.cpp"
    "AAMars.cpp"
    "AAJupiter.cpp"
    "AASaturn.cpp"
    "AAUranus.cpp"
    "AANeptune.cpp"
    "AAPluto.cpp"
    "AAInterpolate.cpp"
    "AAKepler.cpp"
    "AAElliptical.cpp"
    "AAFK5.cpp"
    "AAAberration.cpp"
    "AARefraction.cpp"
    "AAParallax.cpp"
    "AAGlobe.cpp"
    "AADiameters.cpp"
    "AAIlluminatedFraction.cpp"
    "AAElementsPlanetaryOrbit.cpp"
    "AAPrecession.cpp"
)

echo "Building $OUTPUT..."
echo "Compiler: $CXX"
echo "Flags: $CXXFLAGS $DEFINES"
echo ""

# Build the source file list with full paths
SRC_LIST=""
for src in "${SOURCES[@]}"; do
    SRC_LIST="$SRC_LIST $SRCDIR/$src"
done

# Compile (note: UNREFERENCED_PARAMETER macro needs special quoting for bash)
$CXX $CXXFLAGS $DEFINES '-DUNREFERENCED_PARAMETER(x)=' -I"$SRCDIR" $SRC_LIST -o "$SRCDIR/$OUTPUT"

echo ""
echo "Build successful: $SRCDIR/$OUTPUT"
echo ""
echo "Usage examples:"
echo "  $SRCDIR/$OUTPUT 2025-12-10"
echo "  $SRCDIR/$OUTPUT 2025-12-10 -71.05 42.35       # Boston"
echo "  $SRCDIR/$OUTPUT 2025-06-21 -0.1276 51.5074   # London"
echo "  $SRCDIR/$OUTPUT 2025-12-21 -122.4194 37.7749 # San Francisco"
